{"content": "from rich.console import Console
from rich.traceback import install
import sys

def fail():
    try:
        raise ValueError("Original error")
    except ValueError as e:
        e.add_note("Note 1")
        e.add_note("Note 2")
        raise e

if __name__ == "__main__":
    # Create a console that writes to a file
    with open("output.txt", "w") as f:
        console = Console(file=f, width=100, force_terminal=True)
        try:
            fail()
        except Exception:
            console.print_exception()
", "filepath": "reproduction.py"}

{"content": "from rich.traceback import extract
import sys

def fail():
    try:
        raise ValueError("Original error")
    except ValueError as e:
        e.add_note("Note 1")
        e.add_note("Note 2")
        raise e

try:
    fail()
except Exception as e:
    stack = extract(sys.exc_info())
    print(f"Notes: {stack.notes}")
", "filepath": "test_notes_capture.py"}

{"content": "from rich.traceback import Traceback
import sys

def fail():
    try:
        raise ValueError("Original error")
    except ValueError as e:
        e.add_note("Note 1")
        e.add_note("Note 2")
        raise e

try:
    fail()
except Exception as e:
    stack = Traceback.extract(sys.exc_info()[0], sys.exc_info()[1], sys.exc_info()[2])
    print(f"Notes: {stack.notes}")
", "filepath": "test_notes_capture.py"}

