    print(f'type: {type(e.__notes__)}, value: {e.__notes__}')""}

{"command": "python3 -c "from rich.traceback import Traceback;
try:
    raise ValueError('test')
except ValueError as e:
    e.add_note('note 1')
    e.add_note('note 2')
    trace = Traceback.extract(type(e), e, e.__traceback__)
    print(f'Notes: {trace.stacks[0].notes}')""}
